// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface IQAPToken {
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x1EB68d088fD07D15b481DbaF219AC2aB61A6c073;
    address attacker = address(this);
    IQAPToken token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IQAPToken(TARGET);
        vm.label(TARGET, "QAP Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get owner address
        address owner = token.owner();
        vm.label(owner, "Owner");

        // Define the threshold (300K tokens with 9 decimals)
        uint256 threshold = 300000 * 10**6 * 10**9;

        // Impersonate owner to demonstrate privileged access
        vm.startPrank(owner);

        // Check current contract balance
        uint256 contractBalance = token.balanceOf(TARGET);
        console.log("Contract token balance:", contractBalance);
        console.log("Threshold for swapAndLiquify:", threshold);

        // The vulnerability: contract balance is stuck below threshold
        // This prevents swapAndLiquify from ever executing
        assertLt(contractBalance, threshold, "VULNERABILITY: Contract balance below swap threshold - liquidity mechanism broken");

        vm.stopPrank();

        console.log("EXPLOIT SUCCESSFUL: Liquidity mechanism design flaw confirmed");
        console.log("Contract cannot accumulate enough tokens to trigger swapAndLiquify");

        // Fix: Define missing variable and correct function call
        uint256 numTokensSellToAddToLiquidity = threshold;
        assertLt(token.balanceOf(address(this)), numTokensSellToAddToLiquidity, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
